export default async function ({ folder }, ctx) {
  if (!/^[A-Za-z0-9_-]+$/.test(folder) || folder.startsWith("YOUR_"))
    throw Error("Configure style folder");
  let token,
    files = [];
  do {
    const p = await ctx.actions.call("googledrive.files.list", {
      q: "'" + folder + "' in parents and trashed = false",
      pageSize: 100,
      ...(token ? { pageToken: token } : {}),
    });
    if (!Array.isArray(p.files)) throw Error("Invalid Drive listing");
    files.push(...p.files.map((f) => ({ id: f.id, name: f.name })));
    token = p.nextPageToken;
  } while (token);
  return { files };
}

