export default function ({ pairs, previous, collected }) {
  const index = previous?.index ?? 0,
    p = pairs[index],
    items = collected?.items ?? previous?.items ?? [];
  return {
    state: { index: index + (p ? 1 : 0), items },
    more: !!p,
    styleId: p?.styleId ?? "",
    productId: p?.productId ?? "",
  };
}

