export default function ({ styleId, productId, result, previous }) {
  if (
    !Array.isArray(result.prompts) ||
    result.prompts.length !== 10 ||
    result.prompts.some((x) => typeof x !== "string" || !x.trim())
  )
    throw Error("Expected ten prompts");
  return {
    state: {
      items: [
        ...(previous?.items ?? []),
        ...result.prompts.map((prompt, index) => ({ styleId, productId, prompt, index })),
      ],
    },
  };
}

