export default async function ({ item, runId }, ctx) {
  if (!runId.trim()) throw Error("Provide a unique runId");
  const key = "ad-image:" + runId + ":" + item.styleId + ":" + item.productId + ":" + item.index,
    s = await ctx.state.get(key);
  if (s && s.status !== "done") throw Error("Inspect previous action " + key);
  return { key, work: s?.status !== "done" };
}

